mapper.select:
select ses_id as sessionId, ses_candidate_id as candidateId, ses_position_id as positionId
from t_int_session
where ses_id = #{sessionId}

select o.ofr_id as offerId, o.ofr_candidate_id as candidateId, o.ofr_position_id as positionId, o.ofr_salary_offer as salaryOffer, date_format(o.ofr_onboard_date, '%Y-%m-%d') as onboardDate, date_format(o.ofr_deadline, '%Y-%m-%d %H:%i') as deadline, o.ofr_status as status, o.ofr_offer_url as offerUrl, date_format(o.ofr_created_at, '%Y-%m-%d %H:%i') as sentAt, u.nick_name as candidateName, pos.pos_title as positionTitle from t_off_offer o left join t_tal t on t.tal_id = o.ofr_candidate_id left join sys_user u on u.user_id = t.tal_user_id left join t_pos pos on pos.pos_id = o.ofr_position_id
o.ofr_status = #{status}
order by o.ofr_id desc
